impl RateWindow {
    fn new(max: usize, per: Duration) -> Self {
        Self {
            stamps: VecDeque::new(),
            max,
            per,
        }
    }

    fn allow(&mut self, now: Instant) -> bool {
        while self.stamps.front().is_some_and(|&t| now - t >= self.per) {
            self.stamps.pop_front();
